function footprint(): FootprintReport {
  const now = Math.floor(Date.now() / 1000);
  const history = Array.from({ length: 60 }, (_, i) => ({
    t: now - (59 - i) * 2,
    ram_mb: 58 + Math.sin(i / 6) * 3,
    cpu_pct: 0.2 + Math.abs(Math.sin(i / 3)) * 0.4,
  }));
  return {
    ram_mb: 61.4,
    cpu_pct: 0.3,
    processes: [
      { role: "Interface · app core", name: "framewise.exe", count: 1, ram_mb: 9.2, cpu_pct: 0.1 },
      { role: "Interface · WebView2 renderer", name: "msedgewebview2.exe", count: 5, ram_mb: 52.2, cpu_pct: 0.2 },
    ],
    history,
    budget_ram_mb: 100,
    budget_cpu_pct: 2,
    over_budget: false,
  };
}

function live(): LiveStats {
  const t = (Date.now() - startedAt) / 1000;
  return { cpu_pct: 8 + Math.abs(Math.sin(t / 5)) * 6, ram_used_gb: 11.8, ram_total_gb: 32 };
}

const delay = (ms: number) => new Promise((r) => setTimeout(r, ms));
const now = () => Math.floor(Date.now() / 1000);

// ------------------------------------------------------------------ changes (simulated)

const changes: ChangeRow[] = [];
let nextId = 1;
let restorePointMade = false;
const pending = new Set<number>();

const FIX_TEXT: Record<string, [string, string, string]> = {
  refresh_rate: ["Refresh rate · Generic PnP Monitor", "60 Hz", "165 Hz"],
  power_plan: ["Power plan", "Power saver", "Balanced"],
  game_mode: ["Game Mode", "Off", "On"],
  hags: ["Hardware-accelerated GPU scheduling", "Off", "On"],
  windowed_optimizations: ["Optimisations for windowed games", "Off", "On"],
  memory_integrity: ["Memory Integrity", "On", "Off"],
};

const RESTART = new Set(["hags", "memory_integrity"]);

function original(checkId: string) {
  return (mockScan as ScanResult).findings.find((f) => f.check_id === checkId)!;
}

function setFinding(checkId: string, fixed: boolean) {
  if (!scan) return null;
  const o = original(checkId);
  const f = fixed ? { ...o, status: "ok" as const, fix: null, summary: "Fixed by FrameWise (browser preview).", detected: o.expected } : o;
  scan = { ...scan, findings: scan.findings.map((x) => (x.check_id === checkId ? f : x)) };
  scan.score = Math.min(100, Math.max(0, scan.score + (fixed ? 6 : -6)));
  return f;
}

async function progress(steps: string[]) {
  for (const s of steps) {
    emit("task-progress", s);
    await delay(600);
  }
}

interface MockOptions {
  restore_point?: boolean;
  input?: { startup?: { value_name: string }[] };
}

async function applyMock(checkIds: string[], opts: MockOptions, source: string): Promise<FixOutcome> {
  const out: FixOutcome = {
    changes: [],
    already_set: [],
    errors: [],
    restore_point: null,
    findings: [],
    score: null,
    confirm_ids: [],
    confirm_seconds: 0,
  };
  if (opts.restore_point && !restorePointMade) {
    await progress(["Waiting for permission in the Windows prompt…", "Creating a Windows restore point. This can take a minute…"]);
    restorePointMade = true;
    out.restore_point = { id: 1, created_at: now(), sequence: 112, description: "FrameWise: before changes", reused: false };
  }
  for (const id of checkIds) {
    await progress([`Changing ${FIX_TEXT[id]?.[0] ?? id}…`]);
    const rows: [string, string, string][] =
      id === "startup_bloat"
        ? (opts.input?.startup ?? []).map((p) => [`Startup app · ${p.value_name}`, "Enabled", "Disabled"] as [string, string, string])
        : [FIX_TEXT[id] ?? [id, "Before", "After"]];
    for (const [title, oldL, newL] of rows) {
      const row: ChangeRow = {
        id: nextId++,
        check_id: id,
        title,
        old_label: oldL,
        new_label: newL,
        applied_at: now(),
        source,
        reverted_at: null,
        needs_restart: RESTART.has(id),
        restart_pending: RESTART.has(id),
        needs_admin: RESTART.has(id),
        undoable: true,
        detail: null,
      };
      changes.unshift(row);
      out.changes.push(row);
    }
    const f = setFinding(id, true);
    if (f) out.findings.push(f);
  }
  emit("task-progress", "");
  out.score = scan?.score ?? null;
  const refresh = out.changes.filter((c) => c.check_id === "refresh_rate").map((c) => c.id);
  if (refresh.length) {
    out.confirm_ids = refresh;
    out.confirm_seconds = 15;
    refresh.forEach((i) => pending.add(i));
    setTimeout(async () => {
      const still = refresh.filter((i) => pending.delete(i));
      if (still.length) {
        await undoMock(still);
        emit("changes-auto-reverted", still);
      }
    }, 15000);
  }
  return out;
}

async function undoMock(ids: number[]): Promise<UndoOutcome> {
  const out: UndoOutcome = { reverted: [], errors: [], findings: [], score: null };
  for (const id of ids) {
    const c = changes.find((x) => x.id === id);
    if (!c || c.reverted_at) continue;
    await progress([`Undoing ${c.title}…`]);
    c.reverted_at = now();
    c.undoable = false;
    out.reverted.push(id);
    pending.delete(id);
    if (!changes.some((x) => x.check_id === c.check_id && !x.reverted_at)) {
      const f = setFinding(c.check_id, false);
      if (f) out.findings.push(f);
    }
  }
  emit("task-progress", "");
  out.score = scan?.score ?? null;
  return out;
}

