const GB = 1073741824;

function cleanupMock(elevated: boolean): CleanupCategory[] {
  const cat = (
    id: CleanCategoryId,
    title: string,
    description: string,
    needs_admin: boolean,
    recyclable: boolean,
    default_selected: boolean,
    bytes: number,
    items: number,
    needs_permission = false,
  ): CleanupCategory => ({
    id,
    title,
    description,
    needs_admin,
    recyclable,
    default_selected,
    scan: { bytes, items, recent_items: id.endsWith("temp") ? 120 : 0, drivers: [], needs_permission, error: null },
  });
  const cats = [
    cat("user_temp", "Your temporary files", "Files apps left in your Temp folder. Anything changed in the last 24 hours is kept.", false, true, true, 4.6 * GB, 1240),
    cat("windows_temp", "Windows temporary files", "The Windows Temp folder. Anything changed in the last 24 hours is kept.", true, false, true, elevated ? 0.3 * GB : 0, elevated ? 85 : 0, !elevated),
    cat("crash_dumps", "App crash dumps and error reports", "Memory dumps and reports saved when apps crashed. Only useful if you're sending them to a developer.", false, true, true, 0.19 * GB, 10),
    cat("system_crash_dumps", "Windows crash dumps", "Memory dumps from blue screens and driver resets, and queued Windows error reports.", true, false, true, 0.001 * GB, 546, !elevated),
    cat("update_downloads", "Windows Update downloads", "Update files Windows already downloaded more than 10 days ago. Windows downloads them again if it still needs one.", true, false, true, 0.0001 * GB, 1),
    cat("driver_packages", "Old graphics driver packages", "Previous GPU drivers kept in the driver store. The driver in use and the newest older one (for Roll Back Driver) are kept.", true, false, true, 2.1 * GB, 2),
    cat("shader_cache", "GPU shader cache", "Compiled shaders. Only worth clearing if a game stutters after a driver update; games rebuild it, so the first launch is slower.", false, true, false, 13.2 * GB, 697),
  ];
  cats[5].scan.drivers = [
    { inf: "oem95.inf", provider: "NVIDIA", version: "32.0.16.1692", date: "2026-09-04", bytes: 2.6 * GB, in_use: true, kept_for_rollback: false },
    { inf: "oem88.inf", provider: "NVIDIA", version: "32.0.15.8142", date: "2026-06-20", bytes: 2.5 * GB, in_use: false, kept_for_rollback: true },
    { inf: "oem61.inf", provider: "NVIDIA", version: "32.0.15.7270", date: "2026-02-11", bytes: 1.05 * GB, in_use: false, kept_for_rollback: false },
    { inf: "oem40.inf", provider: "NVIDIA", version: "32.0.15.6094", date: "2025-10-02", bytes: 1.05 * GB, in_use: false, kept_for_rollback: false },
  ];
  return cats;
}

async function cleanupRun(categories: string[], permanent: boolean) {
  const cats = cleanupMock(true).filter((c) => categories.includes(c.id));
  const results = [];
  for (const c of cats) {
    await progress([`Cleaning ${c.title.toLowerCase()}…`]);
    const bytes = c.scan.bytes;
    const recycled = c.recyclable && !permanent;
    results.push({ id: c.id, freed_bytes: bytes, removed_items: c.scan.items, skipped_items: c.id === "user_temp" ? 3 : 0, recycled, error: null });
    changes.unshift({
      id: nextId++,
      check_id: "cleanup",
      title: `Cleanup · ${c.title}`,
      old_label: null,
      new_label: null,
      applied_at: now(),
      source: "cleanup",
      reverted_at: null,
      needs_restart: false,
      restart_pending: false,
      needs_admin: false,
      undoable: false,
      detail: `${recycled ? "Moved to the Recycle Bin" : "Deleted"}: ${(bytes / GB).toFixed(1)} GB (${c.scan.items} items)`,
    });
  }
  emit("task-progress", "");
  return {
    results,
    freed_bytes: results.filter((r) => !r.recycled).reduce((a, r) => a + r.freed_bytes, 0),
    recycled_bytes: results.filter((r) => r.recycled).reduce((a, r) => a + r.freed_bytes, 0),
  };
}

