let monitorTimer: ReturnType<typeof setInterval> | null = null;
let benchTimer: ReturnType<typeof setInterval> | null = null;
let tickN = 0;
let nextBenchId = 3;

/** A steady ~144 FPS game with a hitch every few seconds. */
function fakeFrames(n: number, base: number): number[] {
  const out: number[] = [];
  for (let i = 0; i < n; i++) out.push(1000 / base + Math.sin((tickN * n + i) / 7) * 0.4 + (i === 40 && tickN % 4 === 0 ? 18 : 0));
  return out;
}

function stats(avg: number, low1: number, low01: number, duration = 60) {
  return { frames: Math.round(avg * duration), duration_s: duration, avg_fps: avg, low_1: low1, low_01: low01, avg_ms: 1000 / avg, p50_ms: 1000 / avg, p99_ms: 1000 / low1, p999_ms: 1000 / low01, max_ms: 1000 / low01 + 4, stutters: 3 };
}

const benchmarks: BenchmarkRow[] = [
  { id: 1, app: "Cyberpunk2077.exe", label: "Before: Game Mode off", recorded_at: Math.floor(startedAt / 1000) - 3600, duration_s: 60, frames: 8520, avg_fps: 142.1, low_1: 98.4, low_01: 71.2, stats: stats(142.1, 98.4, 71.2), has_frames: true },
  { id: 2, app: "Cyberpunk2077.exe", label: "Before: Game Mode off", recorded_at: Math.floor(startedAt / 1000) - 3400, duration_s: 60, frames: 8580, avg_fps: 143.0, low_1: 99.1, low_01: 70.4, stats: stats(143.0, 99.1, 70.4), has_frames: true },
];

function tick(): MonitorTick {
  tickN++;
  const frames = fakeFrames(144, 144);
  return {
    app: "Cyberpunk2077.exe",
    pid: 4242,
    fps: 143 + Math.sin(tickN / 3) * 2,
    low_1: 101 + Math.sin(tickN / 5) * 3,
    frame_ms: 6.98,
    frames,
    sensors: {
      cpu_pct: 38 + Math.sin(tickN / 4) * 6,
      cpu_perf_pct: 138,
      cpu_cap_pct: 100,
      gpu_pct: 96,
      gpu_temp_c: 71 + Math.sin(tickN / 9) * 2,
      gpu_clock_mhz: 2610,
      gpu_power_w: 152,
      gpu_thermal_throttle: false,
      gpu_power_limited: true,
      ram_used_bytes: 14.2 * 1024 ** 3,
      ram_total_bytes: 32 * 1024 ** 3,
      vram_used_bytes: 6.8 * 1024 ** 3,
      vram_total_bytes: 8 * 1024 ** 3,
    },
    throttling: [],
    presenting: [
      ["Cyberpunk2077.exe", 4242, 143],
      ["Discord.exe", 777, 2],
    ],
  };
}

function startMonitor() {
  if (monitorTimer) return;
  monitor.running = true;
  monitor.mode = "helper";
  monitorTimer = setInterval(() => emit("monitor-tick", tick()), 1000);
}

function stopMonitor() {
  if (monitorTimer) clearInterval(monitorTimer);
  monitorTimer = null;
  monitor.running = false;
  monitor.mode = null;
  emit("monitor-stopped", null);
}

function startBenchmark(req: BenchmarkRequest) {
  startMonitor();
  monitor.benchmarking = true;
  let left = req.delay_s;
  let phase: "countdown" | "recording" = left > 0 ? "countdown" : "recording";
  if (phase === "recording") left = Math.min(req.duration_s, 6);
  benchTimer = setInterval(() => {
    left -= 1;
    if (left <= 0 && phase === "countdown") {
      phase = "recording";
      left = Math.min(req.duration_s, 6); // the preview records 6 s, whatever the length
    } else if (left <= 0) {
      if (benchTimer) clearInterval(benchTimer);
      monitor.benchmarking = false;
      const avg = 150 + Math.random() * 2;
      const run: BenchmarkRow = { id: nextBenchId++, app: "Cyberpunk2077.exe", label: req.label, recorded_at: now(), duration_s: req.duration_s, frames: Math.round(avg * req.duration_s), avg_fps: avg, low_1: 104, low_01: 80, stats: stats(avg, 104, 80, req.duration_s), has_frames: true };
      benchmarks.unshift(run);
      emit("benchmark-done", run);
      return;
    }
    emit("benchmark-progress", { phase, seconds_left: left, app: "Cyberpunk2077.exe", fps: phase === "recording" ? 150 : null });
  }, 1000);
}

