export async function handle<T>(cmd: string, args?: Record<string, unknown>): Promise<T> {
  switch (cmd) {
    case "run_scan":
      await delay(1200);
      scan = { ...(mockScan as ScanResult), started_at: now() };
      return scan as T;
    case "last_scan":
      return scan as T;
    case "recheck": {
      await delay(600);
      const f = (scan ?? (mockScan as ScanResult)).findings.find((x) => x.check_id === args?.checkId);
      return { finding: f, score: scan?.score ?? 0 } as T;
    }
    case "score_history":
      return (scan ? [{ started_at: scan.started_at, score: scan.score }] : []) as T;
    case "footprint":
      return footprint() as T;
    case "live_stats":
      return live() as T;
    case "myths":
      return myths as T;
    case "app_info":
      return { version: "0.4.0 (browser preview)", data_dir: "%LOCALAPPDATA%\\FrameWise", db_ok: true, portable: false } as T;
    case "prepare_update":
      return undefined as T;
    case "crash_reports":
      return crashes as T;
    case "crash_dismiss": {
      const i = crashes.findIndex((c) => c.id === args?.id);
      if (i >= 0) crashes.splice(i, 1);
      return undefined as T;
    }
    case "crash_record":
      return undefined as T;
    case "standby_status":
      return { standby_bytes: 9.2 * 1024 ** 3, ram_total_bytes: 32 * 1024 ** 3, may_help: false } as T;
    case "standby_purge":
      await progress(["Waiting for permission in the Windows prompt…"]);
      emit("task-progress", "");
      return { before: 9.2 * 1024 ** 3, after: 0.3 * 1024 ** 3 } as T;
    case "crash_issue":
    case "watcher_budget_issue": {
      const title = cmd === "crash_issue" ? "Crash: watcher stopped unexpectedly (0.4.0)" : "Watcher over budget (0.4.0)";
      const body = "**FrameWise 0.4.0** · Windows 11 (build 26300) · watcher\n\n(preview text)";
      return { title, body, url: "https://github.com/danieladekunle123/FrameWise/issues/new" } as T;
    }
    case "system_accent":
      return "#0078D4" as T;
    case "open_external":
      window.open(String(args?.uri), "_blank");
      return undefined as T;
    case "apply_fix":
      return (await applyMock([String(args?.checkId)], (args?.options ?? {}) as MockOptions, "manual")) as T;
    case "fix_all_safe": {
      const ids = (scan?.findings ?? []).filter((f) => f.status === "issue" && f.fix?.safe).map((f) => f.check_id);
      return (await applyMock(ids, (args?.options ?? {}) as MockOptions, "fix_all")) as T;
    }
    case "undo_changes":
      return (await undoMock((args?.ids as number[]) ?? [])) as T;
    case "undo_all":
      return (await undoMock(changes.filter((c) => c.undoable && !c.reverted_at).map((c) => c.id))) as T;
    case "confirm_changes":
      ((args?.ids as number[]) ?? []).forEach((i) => pending.delete(i));
      return undefined as T;
    case "change_log":
      return {
        changes,
        restore_points: restorePointMade
          ? [{ id: 1, created_at: Math.floor(startedAt / 1000), sequence: 112, description: "FrameWise: before changes", reused: false }]
          : [],
        restore_point_this_session: restorePointMade,
      } as T;
    case "startup_entries":
      await delay(300);
      return startup as T;
    case "cleanup_scan":
      if (args?.elevated) await progress(["Waiting for permission in the Windows prompt…", "Measuring…"]);
      else await delay(1500);
      emit("task-progress", "");
      return cleanupMock(Boolean(args?.elevated)) as T;
    case "cleanup_run":
      return (await cleanupRun(args?.categories as string[], Boolean(args?.permanent))) as T;
    case "export_report":
      await delay(300);
      return "C:\\Users\\you\\Downloads\\FrameWise report 2026-11-07 19-30.txt" as T;
    case "monitor_status":
      return { ...monitor } as T;
    case "monitor_start":
      await progress(["Waiting for permission in the Windows prompt…"]);
      emit("task-progress", "");
      startMonitor();
      return { ...monitor } as T;
    case "monitor_stop":
      stopMonitor();
      return undefined as T;
    case "monitor_pin":
      monitor.pinned = (args?.pid as number | null) ?? null;
      return undefined as T;
    case "monitor_allow_without_prompt":
      await delay(800);
      return undefined as T;
    case "overlay_set":
      monitor.overlay = Boolean(args?.visible);
      return undefined as T;
    case "benchmark_start":
      startBenchmark(args?.request as BenchmarkRequest);
      return undefined as T;
    case "benchmark_cancel":
      if (benchTimer) clearInterval(benchTimer);
      monitor.benchmarking = false;
      emit("benchmark-failed", "Benchmark cancelled.");
      return undefined as T;
    case "benchmarks_list":
      return [...benchmarks] as T;
    case "benchmark_detail": {
      const run = benchmarks.find((b) => b.id === args?.id);
      if (!run) throw new Error("That run no longer exists.");
      tickN = run.id;
      return { run, graph: fakeFrames(600, run.avg_fps) } as T;
    }
    case "benchmark_rename": {
      const run = benchmarks.find((b) => b.id === args?.id);
      if (run) run.label = String(args?.label ?? "");
      return undefined as T;
    }
    case "benchmark_delete": {
      const i = benchmarks.findIndex((b) => b.id === args?.id);
      if (i >= 0) benchmarks.splice(i, 1);
      return undefined as T;
    }
    case "benchmark_compare": {
      const pick = (ids: number[]) => benchmarks.filter((b) => ids.includes(b.id));
      const b = pick((args?.before as number[]) ?? []);
      const a = pick((args?.after as number[]) ?? []);
      const mean = (v: number[]) => (v.length ? v.reduce((x, y) => x + y, 0) / v.length : 0);
      const spread = (v: number[]) => (v.length < 2 ? 0 : Math.max(...v) - Math.min(...v));
      const metric = (m: "avg_fps" | "low_1" | "low_01") => {
        const bv = b.map((r) => r[m]);
        const av = a.map((r) => r[m]);
        const diff = mean(av) - mean(bv);
        const variation = Math.max(spread(bv), spread(av));
        const verdict = bv.length < 2 || av.length < 2 ? "need_more_runs" : diff > variation ? "better" : -diff > variation ? "worse" : "within_variation";
        return { metric: m, before: mean(bv), after: mean(av), diff, diff_pct: mean(bv) ? (diff / mean(bv)) * 100 : 0, variation, verdict };
      };
      const metrics = [metric("avg_fps"), metric("low_1"), metric("low_01")];
      const sp = (v: BenchmarkRow[]) => (v.length < 2 ? null : (spread(v.map((r) => r.avg_fps)) / mean(v.map((r) => r.avg_fps))) * 100);
      return { comparison: { before_runs: b.length, after_runs: a.length, metrics, verdict: metrics[0].verdict }, before_spread_pct: sp(b), after_spread_pct: sp(a) } as T;
    }
    case "games_list":
      await delay(400);
      return { games: gameRows.map((r) => ({ ...r })), plans: [[BALANCED, "Balanced"], [HIGH, "High performance"], ["e9a42b02-d5df-448d-aa00-03f14749eb61", "Ultimate performance"]], current_plan: BALANCED } as T;
    case "game_add": {
      const path = String(args?.path ?? "");
      if (!path.toLowerCase().endsWith(".exe")) throw new Error("Pick the game's .exe file.");
      const name = path.split(/[\\/]/).pop()!.replace(/\.exe$/i, "");
      const game: Game = { id: `manual:${path.toLowerCase()}`, name, source: "manual", install_dir: null, exe: path };
      if (!gameRows.find((r) => r.game.id === game.id)) gameRows.push({ game, source_label: "Added by you", profile: null });
      return game as T;
    }
    case "game_remove": {
      const i = gameRows.findIndex((r) => r.game.id === args?.id);
      if (i >= 0) gameRows.splice(i, 1);
      return undefined as T;
    }
    case "profile_save": {
      const game = args?.game as Game;
      const row = gameRows.find((r) => r.game.id === game.id);
      const profile = { game_id: game.id, enabled: Boolean(args?.enabled), actions: args?.actions as ProfileActions };
      if (row) row.profile = profile;
      return profile as T;
    }
    case "running_apps":
      await delay(300);
      return [
        { exe: "discord.exe", path: "C:\\Users\\you\\AppData\\Local\\Discord\\app-1.0\\Discord.exe", label: "Discord (overlay)", known_overlay: true },
        { exe: "epicgameslauncher.exe", path: "C:\\Program Files (x86)\\Epic Games\\Launcher\\Portal\\Binaries\\Win64\\EpicGamesLauncher.exe", label: "Epic Games Launcher", known_overlay: true },
        { exe: "lghub.exe", path: "C:\\Program Files\\LGHUB\\lghub.exe", label: "Logitech G HUB", known_overlay: true },
        { exe: "opera.exe", path: "C:\\Users\\you\\AppData\\Local\\Programs\\Opera GX\\opera.exe", label: null, known_overlay: false },
        { exe: "spotify.exe", path: "C:\\Users\\you\\AppData\\Roaming\\Spotify\\Spotify.exe", label: null, known_overlay: false },
      ] as T;
    case "watcher_status":
      return watcherStatusMock() as T;
    case "watcher_enable":
      await delay(500);
      watcher.enabled = Boolean(args?.on);
      watcher.running = watcher.enabled;
      watcher.autostart = watcher.enabled;
      return watcherStatusMock() as T;
    case "watcher_pause":
      watcher.paused = Boolean(args?.paused);
      return undefined as T;
    case "profile_sessions":
      return sessions as T;
    default:
      throw new Error(`Mock has no handler for ${cmd}`);
  }
}
